/**
 * Search Scope brand assets, embedded in the Worker.
 *
 * These were previously hotlinked from searchscope.com.au. That made the
 * landing page of a standalone service depend on another site staying up and
 * serving those exact paths, and it broke the first time that assumption
 * failed. The files are small (the wordmark is under 7 KB), so carrying them
 * here costs almost nothing and removes the dependency entirely.
 *
 * Source of truth is the Search Scope site repository, `public/`. If the brand
 * mark changes there, regenerate this file rather than editing the strings.
 */

/** Horizontal Search Scope wordmark, 660x102 PNG, base64 encoded. */
export const LOGO_PNG_BASE64 =
  "";

/** Square Search Scope mark, 512x512 PNG (the site's maskable icon), base64 encoded. Advertised as the MCP server icon. */
export const ICON_512_PNG_BASE64 =
  "";

/** Search Scope favicon: an SVG wrapper around a small embedded raster mark. */
export const FAVICON_SVG = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\" role=\"img\" aria-label=\"Search Scope\">\n  <image x=\"0\" y=\"0\" width=\"64\" height=\"64\" href=\"data:image/png;base64,\"/>\n</svg>\n";

/** Decode a base64 asset to bytes for a Response body. */
export function decodeBase64(b64: string): Uint8Array {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
